local function kimqRecoveryError(message)
    message=tostring(message or "unknown startup error")
    warn("[Kimqetras HC RECOVERY] "..message)

    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification",{
            Title="Kimqetras HC startup error",
            Text=message:sub(1,220),
            Duration=12,
        })
    end)

    pcall(function()
        local PlayersE=game:GetService("Players")
        local CoreGuiE=game:GetService("CoreGui")
        local lpE=PlayersE.LocalPlayer
        local pgE=lpE and lpE:FindFirstChildOfClass("PlayerGui")
        local parent=CoreGuiE

        local old=CoreGuiE:FindFirstChild("KimqetrasHC_Error")
            or (pgE and pgE:FindFirstChild("KimqetrasHC_Error"))
        if old then old:Destroy() end

        local g=Instance.new("ScreenGui")
        g.Name="KimqetrasHC_Error"
        g.ResetOnSpawn=false
        pcall(function() g.Parent=CoreGuiE end)
        if not g.Parent and pgE then g.Parent=pgE end

        local f=Instance.new("Frame")
        f.AnchorPoint=Vector2.new(.5,.5)
        f.Position=UDim2.fromScale(.5,.5)
        f.Size=UDim2.fromOffset(520,150)
        f.BackgroundColor3=Color3.fromRGB(22,22,28)
        f.BorderSizePixel=0
        f.Parent=g

        local c=Instance.new("UICorner")
        c.CornerRadius=UDim.new(0,10)
        c.Parent=f

        local t=Instance.new("TextLabel")
        t.BackgroundTransparency=1
        t.Position=UDim2.fromOffset(18,14)
        t.Size=UDim2.new(1,-36,1,-28)
        t.Font=Enum.Font.Gotham
        t.TextSize=14
        t.TextWrapped=true
        t.TextXAlignment=Enum.TextXAlignment.Left
        t.TextYAlignment=Enum.TextYAlignment.Top
        t.TextColor3=Color3.fromRGB(255,190,190)
        t.Text="Kimqetras HC stopped while starting.\n\n"..message
        t.Parent=f
    end)
end

local function setProgress(_name)
    completed += 1
end

local function runChunk(name, source, required)
    setProgress(name)
    task.wait(0.03)
    local fn, compileErr = loadstring(source)
    if not fn then
        local msg = name .. " COMPILE: " .. tostring(compileErr)
        table.insert(failures, msg)
        warn("[Kimqetras HC startup] " .. msg)
        Status.Text = msg
        kimqRecoveryError(msg)
        if required then
            Status.Text = Status.Text .. "\ncore could not compile"
            return false
        end
        task.wait(0.2)
        return true
    end

    local ok, runtimeErr = pcall(fn)
    if not ok then
        local msg = name .. " RUNTIME: " .. tostring(runtimeErr)
        table.insert(failures, msg)
        warn("[Kimqetras HC startup] " .. msg)
        Status.Text = msg
        kimqRecoveryError(msg)
        if required then
            Status.Text = Status.Text .. "\ncore could not start"
            return false
        end
        task.wait(0.2)
    end
    return true
end

