        local _,zmin,zmax=cameraTuning()
        local d=cameraDistance()
        if d>1.1 then lastThirdDistance=math.clamp(d,zmin,zmax) end
    end
end)

addSlider("Zoom Speed", 1, 20, _G.KimqCameraZoomSpeed, function(v)
