end)
addSlider("Zoom Max", 5, 50, _G.KimqCameraZoomMax, function(v)
    _G.KimqCameraZoomMax=v
end)
addDecimalSlider("Stay Min", 0, 2, _G.KimqCameraStayMin, 3, function(v)
    _G.KimqCameraStayMin=v
