lp.CharacterAdded:Connect(function(char)
    char.DescendantAdded:Connect(function(v) if ExtraDelayChanger then applyExtraDelay(v) end end)
    if ExtraDelayChanger then task.defer(applyAllExtraDelays) end
end)

