                    ok,mesh=pcall(function()
                        return game:GetService("InsertService"):CreateMeshPartAsync(
                            HEART_MESH,Enum.CollisionFidelity.Box,Enum.RenderFidelity.Precise)
                    end)
                end
                if ok and mesh then heartTemplate=mesh end
            end

