            local rootProperties={Name=true,Size=true,Color=true,Material=true,MaterialVariant=true,TextureID=true,Transparency=true,LocalTransparencyModifier=true,Reflectance=true,CastShadow=true,DoubleSided=true,RenderFidelity=true,Massless=true,PivotOffset=true}
            local excludedProperties={ClassName=true,Archivable=true,WorldCFrame=true,WorldPosition=true,WorldOrientation=true,WorldAxis=true,WorldSecondaryAxis=true,FlipbookSizeX=true,FlipbookSizeY=true}
            local function decodeCaptured(value,objects)
                if type(value)~="table" or not value.Type then return value end
                local kind=value.Type
                if kind=="nil" then return nil end
                if kind=="Instance" then return objects[value.Id] end
                if kind=="Vector3" then return Vector3.new(table.unpack(value.Value)) end
                if kind=="Vector2" then return Vector2.new(table.unpack(value.Value)) end
                if kind=="Color3" then return Color3.new(table.unpack(value.Value)) end
                if kind=="CFrame" then return CFrame.new(table.unpack(value.Value)) end
                if kind=="NumberRange" then return NumberRange.new(value.Min,value.Max) end
                if kind=="EnumItem" then
                    local family,item=value.Value:match("^Enum%.([^.]+)%.(.+)$")
                    return Enum[family][item]
                end
                if kind=="NumberSequence" or kind=="ColorSequence" then
                    local keys={}
                    for _,key in ipairs(value.Keypoints) do
                        if kind=="NumberSequence" then
                            keys[#keys+1]=NumberSequenceKeypoint.new(key.Time,key.Value,key.Envelope or 0)
                        else
                            keys[#keys+1]=ColorSequenceKeypoint.new(key.Time,decodeCaptured(key.Value,objects))
                        end
                    end
                    if kind=="NumberSequence" then return NumberSequence.new(keys) end
                    return ColorSequence.new(keys)
                end
                return nil
            end
            local function applyCaptured(object,name,value,objects)
                pcall(function() object[name]=decodeCaptured(value,objects) end)
            end
            local function capturedFrame(row)
                return CFrame.new(table.unpack(row,2,13))
            end
            local function buildCapturedHeart(track,pos)
                local objects={}
                local heart=heartTemplate:Clone()
                for _,child in ipairs(heart:GetChildren()) do child:Destroy() end
                objects[track.root]=heart
                for _,spec in ipairs(track.objects) do
                    if spec.Id~=track.root then objects[spec.Id]=Instance.new(spec.Class) end
                end
                for _,spec in ipairs(track.objects) do
                    local object=objects[spec.Id]
                    for name,value in pairs(spec.Properties) do
                        if not excludedProperties[name] and (spec.Id~=track.root or rootProperties[name]) then
                            applyCaptured(object,name,value,objects)
                        end
                    end
                    if object:IsA("Trail") then object.Enabled=false; object:Clear()
                    elseif object:IsA("ParticleEmitter") then object.Enabled=false; object:Clear() end
                end
                heart.Anchored=true
                heart.CanCollide=false
                heart.CanTouch=false
                heart.CanQuery=false
                heart.CFrame=CFrame.new(pos)*capturedFrame(track.frames[1])
                heart.Transparency=1
                return {track=track,index=1,eventIndex=1,objects=objects,heart=heart,activeObjects={}}
            end
            local function spawnHearts(pos,force)
                if not force and _G.KimqHeartsKillEnabled~=true then return false end
                if typeof(pos)~="Vector3" then return false end
                if not heartTemplate then
                    warn("[Kimqetras HC] Native heart mesh unavailable. Trigger the original effect once, then try Test Hearts.")
                    return false
                end
                local folder=Instance.new("Folder")
                folder.Name="KimqHeartDeathEffect"
                folder.Parent=workspace
                local states={}
                local endTime=0
                for i,track in ipairs(capturedHeartTracks) do
                    states[i]=buildCapturedHeart(track,pos)
                    endTime=math.max(endTime,track.gone)
                end
                local function cleanup()
                    for _,state in ipairs(states) do
                        for _,object in pairs(state.objects) do pcall(function() object:Destroy() end) end
                    end
                    folder:Destroy()
                end
                local startTime=os.clock()
                local translation=CFrame.new(pos)
                local motionConn
                motionConn=RunService.RenderStepped:Connect(function()
                    if not folder.Parent then motionConn:Disconnect(); cleanup(); return end
                    local age=os.clock()-startTime
                    for _,state in ipairs(states) do
                        local track=state.track
                        if age>=track.gone then
                            if not state.finished then
                                state.finished=true
                                for _,object in pairs(state.objects) do object:Destroy() end
                            end
                        elseif age>=track.frames[1][1] then
                            local frames=track.frames
                            while state.index<#frames and frames[state.index+1][1]<=age do state.index=state.index+1 end
                            local left=frames[state.index]
                            local right=frames[math.min(state.index+1,#frames)]
                            local span=right[1]-left[1]
                            local alpha=span>0 and math.clamp((age-left[1])/span,0,1) or 0
                            -- Set the first visible transform before parenting or emitting.
                            state.heart.CFrame=translation*capturedFrame(left):Lerp(capturedFrame(right),alpha)
                            state.heart.Transparency=left[14]+(right[14]-left[14])*alpha
                            if not state.visible then state.heart.Parent=folder; state.visible=true end
                            for _,spec in ipairs(track.objects) do
                                if not state.activeObjects[spec.Id] and age>=spec.birth then
                                    state.activeObjects[spec.Id]=true
                                    local object=state.objects[spec.Id]
                                    if spec.Id~=track.root then
                                        object.Parent=state.objects[spec.Parent.Id] or state.heart
                                        if object:IsA("Trail") then object:Clear()
                                        elseif object:IsA("ParticleEmitter") then object:Clear() end
                                        if spec.Properties.Enabled~=nil then applyCaptured(object,"Enabled",spec.Properties.Enabled,state.objects) end
                                    end
                                end
                            end
                            while state.eventIndex<=#track.events and track.events[state.eventIndex].time<=age do
                                local event=track.events[state.eventIndex]
                                local object=state.objects[event.id]
                                if object then
                                    if event.remove then object:Destroy()
                                    else applyCaptured(object,event.property,event.value,state.objects) end
                                end
                                state.eventIndex=state.eventIndex+1
                            end
                        end
                    end
                    if age>=endTime then motionConn:Disconnect(); cleanup() end
                end)
                Debris:AddItem(folder,endTime+.75)
                return true
            end

