        local function buildScannedAngelWings(source)
            local objects={};local visual
            local function decode(value)
                if type(value)~="table" then return value end
                if value.Type=="Vector3" then return Vector3.new(table.unpack(value.Value)) end
                if value.Type=="Color3" then return Color3.new(table.unpack(value.Value)) end
                if value.Type=="CFrame" then return CFrame.new(table.unpack(value.Value)) end
                if value.Type=="Instance" then return objects[value.Id] end
                if value.Type=="nil" then return nil end
                if value.Type=="EnumItem" then local family,item=value.Value:match("Enum%.([^%.]+)%.(.+)");return family and Enum[family][item] end
                return nil
            end
            for _,spec in ipairs(scannedWingObjects) do
                local object
                if spec.Class=="MeshPart" then
                    for _,candidate in ipairs(source:GetDescendants()) do
                        if candidate:IsA("MeshPart") and candidate.MeshId==spec.Properties.MeshId then object=candidate:Clone();break end
                    end
                    if not object then error("Scanned wing mesh is unavailable: "..tostring(spec.Properties.MeshId)) end
                    for _,child in ipairs(object:GetChildren()) do child:Destroy() end
                else object=Instance.new(spec.Class) end
                objects[spec.Id]=object
                if spec.Class=="Model" then visual=object end
            end
            for _,spec in ipairs(scannedWingObjects) do
                local object=objects[spec.Id]
                for property,value in pairs(spec.Properties) do
                    if property~="MeshId" and property~="MeshSize" then pcall(function() object[property]=decode(value) end) end
                end
                for name,value in pairs(spec.Attributes or {}) do pcall(function() object:SetAttribute(name,decode(value)) end) end
                if object~=visual then object.Parent=objects[spec.Parent.Id] or visual end
            end
            visual.Name="KimqWornAngelWings"
            visual:SetAttribute("KimqScannedAngelWings",true)
            return visual
        end
        local function applyCapturedWingRig(visual)
            for _,spec in ipairs(capturedWingRig.parts) do
                local part=visual:FindFirstChild(spec.name,true)
                if part and part:IsA("BasePart") then part.Size=Vector3.new(table.unpack(spec.size)) end
            end
            for _,spec in ipairs(capturedWingRig.motors) do
                local motor=visual:FindFirstChild(spec.name,true)
                -- Mesh parts share their joint names, so locate the actual Motor6D.
                if not motor or not motor:IsA("Motor6D") then
                    motor=nil
                    for _,object in ipairs(visual:GetDescendants()) do if object:IsA("Motor6D") and object.Name==spec.name then motor=object;break end end
                end
                if motor then motor.C0=CFrame.new(table.unpack(spec.c0));motor.C1=CFrame.new(table.unpack(spec.c1)) end
            end
        end
