            {"Back / Forward","Z",.02,false},
            {"Pitch","RX",2,true},
            {"Yaw","RY",2,true},
            {"Roll","RZ",2,true},
        }
        local function clampWingFit(k,v)
            if k=="X" or k=="Y" or k=="Z" then return math.clamp(v,-3,3) end
            return math.clamp(v,-180,180)
        end
        local function refreshWingFitLabels()
            for _,row in ipairs(fitRows) do
