    ----------------------------------------------------------------------
    -- LASION SECTION + CONTROL BUILDERS
    ----------------------------------------------------------------------
    local refreshers={}
    local keybindListening=nil
    local toggleKeyActions={}
    local runtimeStatus=nil
    local function reportControlIssue(name,err)
        local message=tostring(name or "Control")..": "..tostring(err or "did not apply")
        _G.KimqLasionLastError=message
        warn("[Kimqetras HC / Lasion] "..message)
        if runtimeStatus and runtimeStatus.Parent then
            runtimeStatus.Text="Issue: "..message:sub(1,160)
            runtimeStatus.TextColor3=Color3.fromRGB(255,155,155)
        end
    end

    UIS.InputBegan:Connect(function(input,gpe)
        if gpe then return end
        if keybindListening and input.UserInputType==Enum.UserInputType.Keyboard then
            local rec=keybindListening
            keybindListening=nil
            if rec.old then toggleKeyActions[rec.old]=nil end
            rec.old=input.KeyCode
            rec.label.Text=input.KeyCode.Name
            toggleKeyActions[input.KeyCode]=rec.action
            return
        end
        local action=toggleKeyActions[input.KeyCode]
        if action then pcall(action) end
    end)

    local visualBalanceQueued=false
    local visualColumnsLocked=false
    local visualBalanceRevision=0
    local function balanceVisualColumns()
        local pg=pages.Visuals
        if not pg or not pg.root.Parent then return end
        local items={}
        for title,api in pairs(pg.sections) do items[#items+1]={title=title,frame=api.frame,height=api.frame.Size.Y.Offset+8} end
        table.sort(items,function(a,b) return a.title<b.title end)
        if #items<2 then return end
        local total=0
        for _,item in ipairs(items) do total=total+item.height end
        local best,assignment=math.huge,{}
        if #items<=14 then
            local chosen={}
            local function search(index,leftHeight)
                if index>#items then
                    local difference=math.abs(total-2*leftHeight)
                    if difference<best then
                        best=difference
                        for i=1,#items do assignment[i]=chosen[i] end
                    end
                    return
                end
                chosen[index]=true;search(index+1,leftHeight+items[index].height)
                chosen[index]=false;search(index+1,leftHeight)
            end
            chosen[1]=true;search(2,items[1].height)
        else
            table.sort(items,function(a,b) if a.height==b.height then return a.title<b.title end return a.height>b.height end)
            local left,right=0,0
            for i,item in ipairs(items) do
                assignment[i]=left<=right
                if assignment[i] then left=left+item.height else right=right+item.height end
            end
        end
        for i,item in ipairs(items) do
            local parent=assignment[i] and pg.left or pg.right
            if item.frame.Parent~=parent then item.frame.Parent=parent end
            item.frame.LayoutOrder=i
        end
    end
    local function queueVisualBalance()
        if visualColumnsLocked then return end
        visualBalanceRevision=visualBalanceRevision+1
        local revision=visualBalanceRevision
        task.delay(.5,function()
            if visualColumnsLocked or revision~=visualBalanceRevision then return end
            balanceVisualColumns()
            visualColumnsLocked=true
        end)
    end
    local function section(tab,title,side)
        local pgx=pages[tab]
        if pgx.sections[title] then return pgx.sections[title] end
        local parent=(side=="right") and pgx.right or pgx.left

        local s=Instance.new("Frame")
        s.Name=title.."Section"
        s.Size=UDim2.new(1,0,0,40)
        s.BackgroundColor3=COL.section
        s.BackgroundTransparency=.4
        s.BorderSizePixel=0
        s.Parent=parent
        corner(s,8)
        stroke(s,COL.stroke,.6,1)
        local sg=Instance.new("UIGradient")
        sg.Transparency=NumberSequence.new({
            NumberSequenceKeypoint.new(0,.3),
            NumberSequenceKeypoint.new(.5,.4),
            NumberSequenceKeypoint.new(1,.5)
        })
        sg.Rotation=45
        sg.Parent=s

        text(s,title,UDim2.new(1,-16,0,20),UDim2.fromOffset(8,6),12,COL.text,Gotham,Enum.TextXAlignment.Left)

        local body=Instance.new("Frame")
        body.Name="Body"
        body.Position=UDim2.fromOffset(0,28)
        body.Size=UDim2.new(1,0,0,0)
        body.BackgroundTransparency=1
        body.Parent=s
        pad(body,8,0,4,8)

        local layout=Instance.new("UIListLayout")
        layout.Padding=UDim.new(0,4)
        layout.SortOrder=Enum.SortOrder.LayoutOrder
        layout.Parent=body

        local order=0
        local function resize()
            local h=layout.AbsoluteContentSize.Y+12
            body.Size=UDim2.new(1,0,0,h)
            s.Size=UDim2.new(1,0,0,28+h)
            if tab=="Visuals" then queueVisualBalance() end
        end
        layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(resize)
        task.defer(resize)

        local api={frame=s,body=body}
        function api:add(obj)
            order+=1
            obj.LayoutOrder=order
            obj.Parent=body
            return obj
        end
        pgx.sections[title]=api
        return api
    end

    local function safeGet(e,default)
        if type(e)=="table" and type(e.get)=="function" then
            local ok,v=pcall(e.get)
            if ok and v~=nil then return v end
            if not ok then reportControlIssue("Reading a setting",v) end
        end
        return default
    end
    local function safeSet(e,v,name)
        if type(e)~="table" or type(e.set)~="function" then
            reportControlIssue(name,"feature backend is unavailable")
            return false
        end
        local ok,result=pcall(e.set,v)
        if not ok or result==false then
            reportControlIssue(name,ok and "setting was rejected" or result)
            return false
        end
        return true
    end

