                    return ""
                end,
                set=function(v) if ctl.SetTarget then return ctl.SetTarget(tostring(v)) end return false end
            }
            textbox(sec,"Avatar Target",target,"username / user id")
            pushButton(sec,"Apply Avatar",function()
                if not ctl.Apply then error("avatar controller is unavailable") end
                if ctl.Apply(target.get())==false then error("avatar could not be applied") end
            end)
            if ctl.ItemOptions and ctl.SetItemHidden then
                local before={};for _,child in ipairs(sec.body:GetChildren()) do before[child]=true end
                local item="Select an item"
                dropdown(sec,"Avatar Item",{get=function() return item end,set=function(v) item=tostring(v) end,meta={}},ctl.ItemOptions)
                pushButton(sec,"Remove Item",function() if ctl.SetItemHidden(item,true)==false then error("select an item from the equipped avatar") end end)
                pushButton(sec,"Restore Item",function() if ctl.SetItemHidden(item,false)==false then error("select an item from the equipped avatar") end end)
                pushButton(sec,"Restore All Items",function() ctl.RestoreAllItems() end)
                local controls={};for _,child in ipairs(sec.body:GetChildren()) do if not before[child] then controls[#controls+1]=child end end
                local function refreshItems()
                    local visible=ctl.IsApplied and ctl.IsApplied()==true
                    for _,control in ipairs(controls) do if control.Parent then control.Visible=visible end end
                end
                table.insert(refreshers,refreshItems)
                if ctl.OnChanged then ctl.OnChanged(refreshItems) end
                refreshItems()
            end
            pushButton(sec,"Reset Avatar",function()
                if not ctl.Reset then error("avatar controller is unavailable") end
                if ctl.Reset()==false then error("avatar could not be reset") end
            end)
        end

        local acc=_G.KimqAccessoryController
