        local frameEffectLayers={}
        local function clearFrameEffects(target)
            local effect=frameEffectLayers[target]
            if not effect then return end
            frameEffectLayers[target]=nil
            if effect.connection then effect.connection:Disconnect() end
            for _,object in ipairs(effect.created) do if object.Parent then object:Destroy() end end
            for object,visible in pairs(effect.hidden) do if object.Parent then object.Visible=visible end end
        end
        local function applyFrameEffects(target,skin)
            local ui=target:FindFirstChild("UI")
            local old=frameEffectLayers[target]
            if old and old.skin==skin and old.ui==ui then return end
            clearFrameEffects(target)
            if skin=="None" or not ui then return end
            local effect={skin=skin,ui=ui,hidden={},created={}}
            frameEffectLayers[target]=effect
            for _,child in ipairs(ui:GetChildren()) do
                if child:IsA("GuiObject") and child.Name~="Main" and not child:GetAttribute("KimqDisplayFrameOwned") then
                    effect.hidden[child]=child.Visible;child.Visible=false
                end
            end
            if skin~="Lightbringer" then return end
            local copies={}
            for _,row in ipairs(lightbringerObjects) do
                local object=Instance.new(row.class);object.Name="KimqFrameEffect_"..row.name
                object:SetAttribute("KimqDisplayFrameOwned",true)
                for property,value in pairs(row.props) do pcall(function() object[property]=value end) end
                object.Parent=copies[row.parent] or ui;copies[row.id]=object;effect.created[#effect.created+1]=object
            end
            local index=1;local elapsed=0;local clock=0
            effect.connection=RunService.RenderStepped:Connect(function(dt)
                if not target.Parent or not ui.Parent then clearFrameEffects(target);return end
                if target.Size.X<.1 or target.Size.Y<.1 or not ui.Enabled then return end
                elapsed=elapsed+dt;clock=clock+dt
                if clock<.05 then return end;clock=0
                if elapsed>26 then elapsed=elapsed%26;index=1 end
                while index<=#lightbringerChanges and lightbringerChanges[index][1]<=elapsed do
                    local change=lightbringerChanges[index];local object=copies[change[2]]
                    if object then object[change[3]]=change[4] end
                    index=index+1
                end
            end)
        end
    local function restore(target)
        clearFrameEffects(target)
        local layer=layers[target]
        if not layer then return end
        layers[target]=nil
        for _,connection in ipairs(layer.connections) do connection:Disconnect() end
        for object,value in pairs(layer.hidden) do if object.Parent then object.Visible=value end end
        for gui,adornee in pairs(layer.guis) do if gui.Parent then gui.Adornee=adornee~=false and adornee or nil end end
        if target.Parent then target.LocalTransparencyModifier=layer.ltm end
        if layer.clone.Parent then layer.clone:Destroy() end
    end
    local function options()
        local result={"None"};local folder=RS:FindFirstChild("Frames")
        if folder then for _,source in ipairs(folder:GetChildren()) do
            local frame=source:FindFirstChild("Frame")
            if source.Name~="None" and frame and frame:IsA("BasePart") then result[#result+1]=source.Name end
        end end
        table.sort(result,function(a,b) if a==b then return false elseif a=="None" then return true elseif b=="None" then return false end return a<b end)
        return result
    end
    local localFramePlayer=game:GetService("Players").LocalPlayer
    local function ownsDisplay(target)
        local slot=target.Name:match("^(Player[1-4])Display$")
        local assignment=slot and target.Parent and target.Parent:FindFirstChild(slot)
        if not assignment or not assignment:IsA("ObjectValue") then return false end
        return assignment.Value==localFramePlayer
    end
    local function applyTarget(target,source,skin)
        if not ownsDisplay(target) then restore(target);return false end
        local layer=layers[target]
        if layer and layer.skin==skin and layer.clone.Parent then applyFrameEffects(target,skin);return true end
        restore(target)
        source.Archivable=true
        local clone=source:Clone()
        if not clone then return false end
        clone.Name="KimqDirectFrame_"..target.Name
        clone:SetAttribute("KimqDirectFrameOwned",true)
        clone.Anchored=true;clone.CanCollide=false;clone.CanTouch=false;clone.CanQuery=false
        clone.LocalTransparencyModifier=0;clone.Size=target.Size;clone.CFrame=target.CFrame
        clone.Parent=target.Parent
        layer={skin=skin,clone=clone,ltm=target.LocalTransparencyModifier,connections={},guis={},hidden={}}
        layers[target]=layer
        target.LocalTransparencyModifier=1
        local function attachUI(gui)
            if not gui:IsA("SurfaceGui") then return end
            if layer.guis[gui]==nil then layer.guis[gui]=gui.Adornee or false end
            gui.Adornee=clone
            -- Preserve player info; hide decorations from the previously equipped skin.
            for _,child in ipairs(gui:GetChildren()) do
                if child:IsA("GuiObject") and child.Name~="Main" and not child:GetAttribute("KimqDisplayFrameOwned") then layer.hidden[child]=child.Visible;child.Visible=false end
            end
        end
        for _,child in ipairs(target:GetChildren()) do attachUI(child) end
        layer.connections[#layer.connections+1]=target:GetPropertyChangedSignal("Size"):Connect(function() if clone.Parent then clone.Size=target.Size end end)
        layer.connections[#layer.connections+1]=target:GetPropertyChangedSignal("CFrame"):Connect(function() if clone.Parent then clone.CFrame=target.CFrame end end)
        layer.connections[#layer.connections+1]=target.ChildAdded:Connect(attachUI)
        for _,linked in ipairs(externalFrameGUIs[source] or {}) do
            if linked.Parent and not linked:IsDescendantOf(source) then
                local linkedCopy=linked:Clone()
                linkedCopy.Name="KimqLinkedFrame_"..linked.Name
                linkedCopy:SetAttribute("KimqDisplayFrameOwned",true)
                linkedCopy.Adornee=clone;linkedCopy.Parent=clone
                for _,script in ipairs(linkedCopy:GetDescendants()) do if script:IsA("LuaSourceContainer") then script:Destroy() end end
            end
        end
        applyFrameEffects(target,skin)
        return true
    end
    local function boxes()
        local ignored=workspace:FindFirstChild("Ignored")
        return ignored and ignored:FindFirstChild("Boxes")
    end
    local function setFrame(skin)
        skin=tostring(skin or "None")
        local source
        if skin~="None" then
            local folder=RS:FindFirstChild("Frames")
            local model=folder and folder:FindFirstChild(skin)
            source=model and model:FindFirstChild("Frame")
            if not source or not source:IsA("BasePart") then return false,"Frame template missing: "..skin end
        end
        state.Skin=skin
        for target in pairs(layers) do if not ownsDisplay(target) then restore(target) end end
        local root=boxes();local count=0
        if skin=="None" then for target in pairs(layers) do restore(target) end;return true,"Original frames restored" end
        if root then for _,target in ipairs(root:GetDescendants()) do
            if target:IsA("BasePart") and target.Name:match("^Player[1-4]Display$") and applyTarget(target,source,skin) then count=count+1 end
        end end
        sharedEnv.KimqFrameApplyDebug={Skin=skin,AppliedDisplays=count}
        return true,count>0 and (skin.." applied to "..count.." displays") or "Frame saved; waiting for fight displays"
    end
    local queued=false
    local function queueApply()
        if queued then return end;queued=true
        task.defer(function() queued=false;if state.Skin~="None" then setFrame(state.Skin) end end)
    end
    local watchedSlots=setmetatable({},{__mode="k"})
    local function watchSlot(object)
        if not object:IsA("ObjectValue") or not object.Name:match("^Player[1-4]$") or watchedSlots[object] then return end
        watchedSlots[object]=true
        connections[#connections+1]=object:GetPropertyChangedSignal("Value"):Connect(queueApply)
    end
    local root=boxes()
    if root then
        for _,object in ipairs(root:GetDescendants()) do watchSlot(object) end
        connections[#connections+1]=root.DescendantAdded:Connect(function(object)
            watchSlot(object)
            if object:IsA("ObjectValue") and object.Name:match("^Player[1-4]$") then queueApply() end
            if object:IsA("BasePart") and object.Name:match("^Player[1-4]Display$") then queueApply()
            elseif object:IsA("GuiObject") and object.Parent and object.Parent.Name=="UI" then
                local layer=layers[object.Parent.Parent]
                if layer and object.Name~="Main" and not object:GetAttribute("KimqDisplayFrameOwned") then layer.hidden[object]=object.Visible;object.Visible=false end
            end
        end)
        connections[#connections+1]=root.DescendantRemoving:Connect(function(object)
            if layers[object] then restore(object) end
            if object:IsA("ObjectValue") and object.Name:match("^Player[1-4]$") then queueApply() end
        end)
    end
    local ctl={FrameOptions=options,GetFrame=function() return state.Skin end,SetFrame=setFrame,Refresh=function() return setFrame(state.Skin) end}
    function ctl.Destroy()
        controllerAlive=false
        for _,connection in ipairs(connections) do connection:Disconnect() end
        for target in pairs(layers) do restore(target) end
    end
    task.spawn(function()
        for i,object in ipairs(RS:GetDescendants()) do
            if not controllerAlive then return end
            registerLinkedGUI(object)
            if i%300==0 then task.wait() end
        end
        referencesReady=true
        if state.Skin~="None" then
            for target in pairs(layers) do restore(target) end
            setFrame(state.Skin)
        end
    end)
    connections[#connections+1]=RS.DescendantAdded:Connect(function(object)
        registerLinkedGUI(object)
        if referencesReady and (object:IsA("SurfaceGui") or object:IsA("BillboardGui")) then
            local root=object.Adornee
            for target,layer in pairs(layers) do
                local folder=RS:FindFirstChild("Frames");local model=folder and folder:FindFirstChild(layer.skin)
                if model and model:FindFirstChild("Frame")==root then restore(target) end
            end
            queueApply()
        end
    end)
    sharedEnv.KimqDirectFrameController=ctl;sharedEnv.KimqCharacterCosmeticsController=ctl;_G.KimqCharacterCosmeticsController=ctl
    if state.Skin~="None" then setFrame(state.Skin) end
    return ctl
end

