-- Local practice clones v6. All health and hit feedback stays on this client.
local function installPracticeBots(section, COL, Gotham, gui)
 local Players=game:GetService('Players')
 local Run=game:GetService('RunService')
 local UIS=game:GetService('UserInputService')
 local player=Players.LocalPlayer
 if _G.KimqPracticeBots then _G.KimqPracticeBots:Destroy()end
 local B={connections={},bots={},frames={},parts={},recording=false,loop=true,damage=25,selected=0,alive=true,shots=0,hits=0}
 _G.KimqPracticeBots=B
 local folder=Instance.new('Folder');folder.Name='KimqLocalPracticeBots';folder.Parent=workspace
 local template,recordingCharacter,startTime,watchedTool
 local lastSample,lastFire,lastEvidence=0,-100,-100
 local gunConnections={};local held=false;local nextId=0
 local avatarTemplate,avatarName,avatarDisplay;local avatarBusy=false
 local mouse=player:GetMouse()
 local summary=section('Bots','Practice bots','left')
 local sec=section('Bots','Record & replay','right')
 local refreshBotPicker=function()end
 local function label(sec,height)
  local t=Instance.new('TextLabel');t.Size=UDim2.new(1,0,0,height);t.BackgroundTransparency=1;t.TextColor3=COL.text;t.FontFace=Gotham;t.TextSize=12;t.TextWrapped=true;sec:add(t);return t
 end
 local status=label(summary,42)
 local shotStatus=label(summary,42)
 local shotMessage='Equip a gun to test local damage.'
 local function say(s)if status.Parent then status.Text=s end end
 local function connect(signal,fn)local c=signal:Connect(fn);table.insert(B.connections,c);return c end
 local function button(parent,title,fn)
  local b=Instance.new('TextButton');b.Size=UDim2.new(1,-4,0,34);b.BackgroundColor3=COL.section;b.TextColor3=COL.text;b.FontFace=Gotham;b.TextSize=12;b.TextWrapped=true;b.Text=title;b.BorderSizePixel=0
  local corner=Instance.new('UICorner');corner.CornerRadius=UDim.new(0,6);corner.Parent=b;parent:add(b)
  local function activate()local ok,err=pcall(fn);if not ok then say(tostring(err):sub(1,150))end end
  if parent.rows then b.Activated:Connect(activate)else connect(b.Activated,activate)end;return b
 end
 local function keyOf(part,root)
  local path={};local node=part
  while node and node~=root do
   local rank=0
   for _,sibling in ipairs(node.Parent:GetChildren())do
    if sibling.Name==node.Name and sibling.ClassName==node.ClassName then rank=rank+1 end
    if sibling==node then break end
   end
   table.insert(path,1,node.ClassName..':'..node.Name..':'..rank);node=node.Parent
  end
  return table.concat(path,'/')
 end
 local function clean(model)
  -- Preserve Humanoid, scales, clothing, face, WrapLayers, attachments and rig joints.
  -- Recorded world-space poses own movement; disable joints instead of deleting them.
  for _,o in ipairs(model:GetDescendants())do
   if o:IsA('LuaSourceContainer')or o:IsA('BodyMover')or o:IsA('Sound')or o:IsA('BillboardGui')or o:IsA('SurfaceGui')or o:IsA('Tool')then o:Destroy()
   elseif o:IsA('JointInstance')or o:IsA('WeldConstraint')or o:IsA('AnimationConstraint')then
    local a,b=o.Part0,o.Part1
    if not a or not b or not a:IsDescendantOf(model)or not b:IsDescendantOf(model)then o:Destroy()
    else pcall(function()o.Enabled=false end)end
   elseif o:IsA('Constraint')then o:Destroy()
   elseif o:IsA('BasePart')then
    o.Anchored=true;o.CanCollide=false;o.CanTouch=false;o.CanQuery=false
    o.LocalTransparencyModifier=0;o.AssemblyLinearVelocity=Vector3.zero;o.AssemblyAngularVelocity=Vector3.zero
   elseif o:IsA('ParticleEmitter')or o:IsA('Trail')or o:IsA('Beam')then o.Enabled=false end
  end
  for _,name in ipairs({'BodyEffects','K.O','KO','Knocked','Downed','Dead','Unconscious','GRABBING_CONSTRAINT','Grabbed'})do
   local flag=model:FindFirstChild(name);if flag then flag:Destroy()end
  end
  local h=model:FindFirstChildOfClass('Humanoid')
  if h then
   h.BreakJointsOnDeath=false;h.RequiresNeck=false;h.AutoRotate=false
   h.MaxHealth=100;h.Health=100;h.DisplayName=player.DisplayName
   h.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.Viewer
   h.HealthDisplayType=Enum.HumanoidHealthDisplayType.DisplayWhenDamaged
   h.NameDisplayDistance=100;h.HealthDisplayDistance=100
   pcall(function()h.EvaluateStateMachine=false end)
   local animator=h:FindFirstChildOfClass('Animator')
   if animator then for _,track in ipairs(animator:GetPlayingAnimationTracks())do track:Stop(0)end end
  end
 end
 local function stopRecord()
  if not B.recording then return end
  B.recording=false;say(('Saved %.1fs • Shift+9 to spawn'):format(B.frames[#B.frames]and B.frames[#B.frames].t or 0))
 end
 local function record()
  if B.recording then stopRecord();return end
  local c=player.Character;local root=c and c:FindFirstChild('HumanoidRootPart')
  if not root then say('Wait for your character to spawn.');return end
  local arch=c.Archivable;c.Archivable=true;local ok,copy=pcall(function()return c:Clone()end);c.Archivable=arch
  if not ok or not copy then say('Could not copy your character.');return end
  clean(copy)
  if template then template:Destroy()end;template=copy
  B.parts={};B.frames={};B.keys={}
  for _,o in ipairs(c:GetDescendants())do
   if o:IsA('BasePart')and #B.parts<160 then table.insert(B.parts,o);table.insert(B.keys,keyOf(o,c))end
  end
  recordingCharacter=c;startTime=os.clock();lastSample=0;B.recording=true
  say('Recording • Shift+8 to stop • max 60 seconds')
 end
 local function selected()return B.bots[B.selected]end
 function B:GetCandidates()
  local out={}
  if not self.alive or self.aimEnabled==false then return out end
