 local function poseBot(bot,a,z,alpha)
  if not bot.retarget then
   for i,part in pairs(bot.parts)do if part.Parent and a.poses[i] and z.poses[i]then part.CFrame=a.poses[i]:Lerp(z.poses[i],alpha)end end
   return
  end
