  local ri=bot.sourceIndices.HumanoidRootPart
  if not root or not ri then return end
  root.CFrame=a.poses[ri]:Lerp(z.poses[ri],alpha)
  local placed={[root]=true}
  for _=1,16 do
   local changed=false
   for _,j in ipairs(bot.joints)do
    if j.Part0 and j.Part1 and placed[j.Part0]and not placed[j.Part1]then
     local transform=CFrame.new();local source=bot.sourceJoints[j.Name]
     if (j:IsA('Motor6D')or j:IsA('AnimationConstraint'))and source then
      local i,k=source.i,source.k
      if i and k and a.poses[i]and a.poses[k]and z.poses[i]and z.poses[k]then
       local x=source.c0:Inverse()*a.poses[i]:Inverse()*a.poses[k]*source.c1
       local y=source.c0:Inverse()*z.poses[i]:Inverse()*z.poses[k]*source.c1
       local rotation=x:Lerp(y,alpha);transform=rotation-rotation.Position
      end
     end
     j.Part1.CFrame=j.Part0.CFrame*j.C0*transform*j.C1:Inverse()
     placed[j.Part1]=true;changed=true
    end
   end
   if not changed then break end
  end
 end
