 local function hurt(bot,amount)
  if bot.health<=0 then return end
  bot.health=math.max(0,bot.health-amount)
  if bot.humanoid then bot.humanoid.Health=bot.health end
  if bot.health==0 then bot.playing=false;ragdoll(bot)end
 end
 local function gunNumber(tool,names)
  for _,name in ipairs(names)do
   local attr=tonumber(tool:GetAttribute(name));if attr then return attr end
   local v=tool:FindFirstChild(name,true)
   if v and(v:IsA('NumberValue')or v:IsA('IntValue')or v:IsA('StringValue'))then local n=tonumber(v.Value);if n then return n end end
  end
 end
 local ammoNames={'Ammo','Clip','CurrentAmmo','AmmoCount','Bullets'}
 local automaticNames={ar=true,ak47=true,smg=true,lmg=true,p90=true,drumgun=true,silencerar=true}
 local function automatic(tool)return tool:GetAttribute('Automatic')==true or automaticNames[tool.Name:lower():gsub('[%[%]%s%-]','')]==true end
 local function isGun(tool)
  if not tool or not tool:IsA('Tool')then return false end
  local n=tool.Name:lower()
  for _,word in ipairs({'knife','wallet','phone','combat','food'})do if n:find(word,1,true)then return false end end
  if gunNumber(tool,ammoNames)~=nil or automatic(tool)then return true end
  for _,word in ipairs({'db','revolver','shotgun','silencer','smg','pistol','rifle','drumgun','glock','uzi','ak47','aug','p90','lmg','double-barrel','tactical'})do if n:find(word,1,true)then return true end end
  return tool:FindFirstChild('ShootSound',true)~=nil
 end
 local function gunEquipped()
  local c=player.Character;if not c then return end
  for _,t in ipairs(c:GetChildren())do if isGun(t)then return t end end
 end
 local function blocked(tool)
  local c=player.Character;local h=c and c:FindFirstChildOfClass('Humanoid')
  if tool.Parent~=c or not h or h.Health<=0 then return true end
  local body=c:FindFirstChild('BodyEffects')
  if body then for _,n in ipairs({'Reload','K.O','Dead','Cuff'})do local v=body:FindFirstChild(n);if v and v.Value==true then return true end end end
  return tool:GetAttribute('Reloading')==true or tool:GetAttribute('Reload')==true
 end
 -- Body-only ray/box test does not depend on collision groups or CanQuery.
 local function boxDistance(part,origin,direction,range)
  local o=part.CFrame:PointToObjectSpace(origin)
  local d=part.CFrame:VectorToObjectSpace(direction)
  local half=part.Size*.5;local lo,hi=0,range
  for _,axis in ipairs({'X','Y','Z'})do
   if math.abs(d[axis])<.000001 then
    if math.abs(o[axis])>half[axis]then return nil end
   else
    local a=(-half[axis]-o[axis])/d[axis];local b=(half[axis]-o[axis])/d[axis]
    if a>b then a,b=b,a end
    lo=math.max(lo,a);hi=math.min(hi,b);if lo>hi then return nil end
   end
  end
  return lo
 end
 local function botHit(ray,range)
  local best,hit
  local direction=ray.Direction.Unit
  for _,bot in ipairs(B.bots)do if bot.health>0 and bot.model.Parent then
   for _,part in ipairs(bot.bodyParts)do if part.Parent then
    local distance=boxDistance(part,ray.Origin,direction,range)
    if distance and(not best or distance<best)then best=distance;hit={Instance=part,Position=ray.Origin+direction*distance}end
   end end
  end end
  return hit
 end
 local function shot(source,confirmed)
  local tool=watchedTool
  if not tool or blocked(tool)or #B.bots==0 then return end
  local now=os.clock()
  if confirmed then lastEvidence=now end
  -- Activated, ammo change and sound can describe the same shot; count it once.
  local gap=math.clamp(gunNumber(tool,{'ShootingCooldown','FireDelay','ShotCooldown'})or .09,.045,.12)
  if now-lastFire<gap then return end
  local ammo=gunNumber(tool,ammoNames)
  if not confirmed and ammo and ammo<=0 then shotMessage='Empty gun • no simulated shot';return end
  lastFire=now;B.shots=B.shots+1
  local camera=workspace.CurrentCamera;if not camera then return end
  -- Mouse.UnitRay matches the game's pointer in windowed and shift-lock play.
  local ray=mouse.UnitRay
  if B.aimEnabled~=false then
   local resolver=rawget(_G,_G.HCSilentAimEnabled and 'KimqPracticeHCShot'or 'KimqPracticeSilentShot')
   if type(resolver)=='function'then
    local ok,part,point=pcall(resolver)
    if ok and part and typeof(point)=='Vector3'and part:IsDescendantOf(folder)then
     local delta=point-ray.Origin
     if delta.Magnitude>.001 then ray=Ray.new(ray.Origin,delta.Unit);source=source..' + Silent Aim'end
    end
   end
  end
  local range=math.clamp(gunNumber(tool,{'Range'})or 500,1,2000)
