  if not hit then shotMessage=source..' • miss';return end
  -- Find clone first so transparent VFX cannot swallow its hit. Then respect walls.
  local walls=RaycastParams.new();walls.FilterType=Enum.RaycastFilterType.Exclude;walls.FilterDescendantsInstances={player.Character,folder};walls.RespectCanCollide=true;walls.IgnoreWater=true
  local function clear(origin)
   local delta=hit.Position-origin
   if delta.Magnitude<.01 then return true end
   local wall=workspace:Raycast(origin,delta,walls)
   return not wall or(wall.Position-origin).Magnitude>=delta.Magnitude-.15
  end
  local handle=tool:FindFirstChild('Handle',true)
  if not clear(ray.Origin)then shotMessage=source..' • blocked by wall';return end
  for _,bot in ipairs(B.bots)do
   if bot.health>0 and hit.Instance:IsDescendantOf(bot.model)then
    hurt(bot,B.damage);B.hits=B.hits+1
    shotMessage=source..' • HIT clone '..bot.id..' • '..bot.health..'/100';return
   end
  end
 end
 local function clearGun()
  for _,c in ipairs(gunConnections)do c:Disconnect()end
  gunConnections={};held=false;watchedTool=nil;lastEvidence=-100
 end
 local function watchGun(force)
  local tool=gunEquipped();if tool==watchedTool and not force then return end
  clearGun();watchedTool=tool;lastFire=-100;lastEvidence=-100
  if not tool then shotMessage='Equip a gun to test local damage.';return end
  local function listen(signal,fn)table.insert(gunConnections,signal:Connect(fn))end
  local function fire(source,confirmed)
   local ok,err=pcall(shot,source,confirmed);if not ok then shotMessage='Hit check error: '..tostring(err):sub(1,90)end
  end
  listen(tool.Activated,function()held=true;fire('Trigger',false)end)
  listen(tool.Deactivated,function()held=false end)
  listen(tool.Unequipped,function()held=false end)
  local monitored={}
  local function observe(o)
   if monitored[o]then return end;monitored[o]=true
   if (o:IsA('IntValue')or o:IsA('NumberValue')or o:IsA('StringValue'))and table.find(ammoNames,o.Name)then
    local before=tonumber(o.Value)
    listen(o.Changed,function(v)local n=tonumber(v);local old=before;before=n;if old and n and n<old then fire('Ammo',true)end end)
   elseif o:IsA('Sound')then
    local n=o.Name:lower()
    if n=='shootsound'or n=='shoot'or n=='fire'or n=='gunshot'then listen(o.Played,function()fire('Gun sound',true)end)end
   end
  end
  for _,o in ipairs(tool:GetDescendants())do observe(o)end
  listen(tool.DescendantAdded,observe)
  for _,name in ipairs(ammoNames)do
   local before=tonumber(tool:GetAttribute(name))
   listen(tool:GetAttributeChangedSignal(name),function()local n=tonumber(tool:GetAttribute(name));local old=before;before=n;if old and n and n<old then fire('Ammo attribute',true)end end)
  end
  shotMessage='Watching '..tool.Name..' • trigger / ammo / sound'
 end
 local function directFire()
