   if o:IsA('GuiObject')and o.Visible and o.Active then
    local v=o;local visible=true
    while v and v~=gui do if v:IsA('GuiObject')and not v.Visible then visible=false;break end;v=v.Parent end
    local q,z=o.AbsolutePosition,o.AbsoluteSize
    if visible and gui.Enabled and p.X>=q.X and p.X<=q.X+z.X and p.Y>=q.Y and p.Y<=q.Y+z.Y then over=true;break end
   end
  end
