  local holder=Instance.new('ScrollingFrame');holder.Size=UDim2.new(1,-4,0,height);holder.BackgroundTransparency=1;holder.BorderSizePixel=0
  holder.ScrollBarThickness=3;holder.ScrollBarImageColor3=COL.text;holder.AutomaticCanvasSize=Enum.AutomaticSize.Y
  holder.CanvasSize=UDim2.new();holder.ScrollingDirection=Enum.ScrollingDirection.Y;holder.Visible=false
  local layout=Instance.new('UIListLayout');layout.Padding=UDim.new(0,4);layout.Parent=holder
  local toggle=button(parent,title..' ▾',function()expanded=not expanded;holder.Visible=expanded end)
  parent:add(holder)
  local api={holder=holder,toggle=toggle,rows={}}
  function api:add(o)o.Parent=holder;table.insert(self.rows,o);o.LayoutOrder=#self.rows end
  function api:clear()for _,row in ipairs(self.rows)do row:Destroy()end;self.rows={}end
  function api:choose(name)toggle.Text=name..' ▾';expanded=false;holder.Visible=false end
  return api
 end
 local botPicker=picker(summary,'Select a bot',115)
