 local appearance=section('Bots','Avatar & spawn','left')
 local entry=Instance.new('TextBox');entry.Size=UDim2.new(1,-4,0,34);entry.BackgroundColor3=COL.section;entry.TextColor3=COL.text;entry.FontFace=Gotham;entry.TextSize=12;entry.Text='';entry.PlaceholderText='Roblox username or numeric user ID';entry.ClearTextOnFocus=false;appearance:add(entry)
