 local characterCollisionConnection
 local function watchCharacterCollision(c)
  if characterCollisionConnection then characterCollisionConnection:Disconnect();characterCollisionConnection=nil end
  for _,bot in ipairs(B.bots)do protectCorpse(bot)end
  if c then characterCollisionConnection=c.DescendantAdded:Connect(function(part)
   if not part:IsA('BasePart')then return end
   for _,bot in ipairs(B.bots)do if bot.dead and bot.model.Parent then
    local group=bot.model:FindFirstChild('PracticePlayerNoCollision')
    if group then for _,body in ipairs(bot.collisionParts or bot.bodyParts)do if body.Parent then noCollision(body,part,group)end end end
   end end
  end)end
 end
 connect(player.CharacterAdded,watchCharacterCollision)
 watchCharacterCollision(player.Character)

 local poll=0
 connect(Run.RenderStepped,function(dt)
  if not B.alive then return end
  poll=poll+dt
  if poll>=.1 then
   poll=0;watchGun()
   shotStatus.Text=shotMessage..'\nDetected '..B.shots..' shots • '..B.hits..' hits (local)'
  end
  -- Automatic fire fallback when the game does not expose ammo/sound updates.
  if held and watchedTool and automatic(watchedTool) then
   local gap=math.max(gunNumber(watchedTool,{'ShootingCooldown','FireDelay'})or .12,.06)
   if os.clock()-lastEvidence>math.max(.18,gap*2)and os.clock()-lastFire>=gap then
    local ok,err=pcall(shot,'Held trigger',false);if not ok then shotMessage=tostring(err):sub(1,100)end
   end
  end
  if B.recording then
   if player.Character~=recordingCharacter then stopRecord()
   else local elapsed=os.clock()-startTime
    if elapsed-lastSample>=1/30 or #B.frames==0 then
     lastSample=elapsed;local poses={}
     for i,part in ipairs(B.parts)do poses[i]=part.Parent and part.CFrame or(B.frames[#B.frames]and B.frames[#B.frames].poses[i])or CFrame.new()end
     table.insert(B.frames,{t=elapsed,poses=poses})
    end
    if elapsed>=60 or #B.frames>=1800 then stopRecord()end
   end
  end
  for _,b in ipairs(B.bots)do if b.playing and b.health>0 and b.model.Parent then
   b.time=b.time+dt;local frames=b.frames;local duration=frames[#frames].t
   if b.time>=duration then if B.loop then b.time=b.time%duration;b.index=1 else b.time=duration;b.playing=false end end
   while b.index<#frames-1 and frames[b.index+1].t<b.time do b.index=b.index+1 end
   local a,z=frames[b.index],frames[math.min(b.index+1,#frames)];local alpha=math.clamp((b.time-a.t)/math.max(z.t-a.t,.0001),0,1)
   poseBot(b,a,z,alpha)
  end end
 end)
 function B:Destroy()
  if not self.alive then return end;self.alive=false;clearGun()
  if characterCollisionConnection then characterCollisionConnection:Disconnect()end
  for _,c in ipairs(self.connections)do c:Disconnect()end
  for _,b in ipairs(self.bots)do b.template:Destroy()end
  if avatarTemplate then avatarTemplate:Destroy()end
  if template then template:Destroy()end;folder:Destroy();self.bots={};self.frames={};self.parts={}
  if _G.KimqPracticeBots==self then _G.KimqPracticeBots=nil end
 end
